function makeOptions(item, salt) {
  const [question, correct, distractor1, distractor2, explanation] = item;
  const values = [correct, distractor1, distractor2];
  // Urutan opsi diacak deterministik agar jawaban benar tidak selalu berada di posisi pertama.
  let seed = 2166136261;
  for (const ch of salt) seed = Math.imul(seed ^ ch.charCodeAt(0), 16777619) >>> 0;
  for (let i = values.length - 1; i > 0; i -= 1) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    const j = seed % (i + 1);
    [values[i], values[j]] = [values[j], values[i]];
  }
  return { question, options: values, answer: values.indexOf(correct), explanation };
}

const CLASSIC_QUESTIONS = [];
for (const subject of SUBJECTS) {
  const groups = BANK[subject];
  if (!groups) throw new Error(`Tidak ada bank soal untuk mata pelajaran ${subject}`);
  for (const difficulty of DIFFICULTIES) {
    const items = [...groups[difficulty], ...EXTRA_BANK[subject][difficulty]];
    if (!Array.isArray(items) || items.length < 10) throw new Error(`Bank ${subject}/${difficulty} minimal 10 soal`);
    items.forEach((item, index) => {
      const salt = `${subject}|${difficulty}|${index}`;
      const prepared = makeOptions(item, salt);
      const base = {
        id: `CLASSIC-${subject.replace(/[^A-Za-z0-9]+/g, '-').toUpperCase()}-${difficulty.toUpperCase()}-${String(index + 1).padStart(2, '0')}`,
        subject,
        difficulty,
        ...prepared,
        conceptKey: `${subject}|${difficulty}|${index + 1}`,
        sourceRefs: SOURCE_URLS[subject].map((url) => ({ url, title: 'Referensi soal cerdas cermat dan materi terkait', kind: 'reference' })),
        sourceNote: 'Soal ditulis ulang sebagai soal cerdas cermat orisinal dengan rujukan materi terkait; bukan salinan massal teks artikel.',
        sourceMode: 'classic-curated',
        generated: false,
      };
      // Soal dasar yang umum dipakai dalam cerdas cermat tersedia lintas jenjang.
      // Kesulitan ditentukan oleh bank mudah/sedang/sulit, bukan dengan membuat kalimat acak.
      for (const level of LEVELS) CLASSIC_QUESTIONS.push({ ...base, id: `${base.id}-${level.toUpperCase()}`, level, conceptKey: `${base.conceptKey}|${level}`, options: [...base.options], sourceRefs: [...base.sourceRefs] });
    });
  }
}

module.exports = { CLASSIC_QUESTIONS, CLASSIC_SOURCE_URLS: SOURCE_URLS };
